#!/usr/bin/env bash
#
# Build the Zenodo data bundle (author-side script — users do not run this).
#
# Collects only the artifacts that cannot be regenerated by the repository's own
# scripts, plus the simulated dataset (generable, but ~2h45m of GPU time, so it is
# shipped for convenience). See data/MANIFEST.md for the full rationale.
#
# Run this on BARE METAL, from the repository root. It is plain bash + tar and
# needs no Python, Taichi or CUDA, so there is nothing Docker adds.
#
# Usage:
#   ./data/make_data_bundle.sh [SOURCE_DIR] [OUTPUT_TAR]
#
#   SOURCE_DIR   Repository-shaped tree holding the full data. Defaults to THIS
#                repository, which is the authoritative copy - the meat trial
#                rename and trim live here, as do the renamed checkpoint paths.
#                You normally want the default.
#   OUTPUT_TAR   Destination .tar.gz (default: ./shallow-vessel-palpation-data.tar.gz)
#
# The script REFUSES to write a tarball if any path it wants is absent from
# SOURCE_DIR, listing everything missing in one go: each of them is either
# unregenerable or hours of GPU time, so a gap is a broken artifact rather than
# something to warn about. Override with DIFFTACTILE_BUNDLE_ALLOW_MISSING=1.
#
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"

# The repository itself is the default source, because the working tree is the
# authoritative copy of the data: the meat dataset's descriptive trial names and
# its trim to the 10 trials the model uses were both done here, and the renamed
# checkpoint/pickle paths only exist here.
#
# The author's frozen submission-state snapshot lives OUTSIDE this repository at
#
#   /home/psb120/Documents/phd/data/masters/diff-tactile-fork-IROS-submission-state/diff-tactile-fork
#
# and is now an explicit opt-in (pass it as the first argument) rather than the
# default. It PREDATES the rename - its meat data is under `iros_training_data/`
# with 23 bare-timestamp trials, and it has neither `saved_models_{sim,meat}/`
# nor the `test_loader_gnn_*.pickle` files under those names - so bundling from
# it silently produced an archive missing the meat data, both checkpoints, both
# pickles and the silicone dataset. That is exactly what the strict `copy_tree` /
# `copy_file` below now refuses to do.
SOURCE_DIR="${1:-${REPO_DIR}}"
OUTPUT_TAR="${2:-${REPO_DIR}/shallow-vessel-palpation-data.tar.gz}"

if [ ! -d "${SOURCE_DIR}" ]; then
    echo "ERROR: source tree not found: ${SOURCE_DIR}" >&2
    exit 1
fi

STAGE="$(mktemp -d)"
trap 'rm -rf "${STAGE}"' EXIT
BUNDLE="${STAGE}/shallow-vessel-palpation-data"
mkdir -p "${BUNDLE}"

echo "Source: ${SOURCE_DIR}"
echo "Staging in: ${BUNDLE}"
echo

# copy_tree <relative-path> [find-filter...]
# Copies SOURCE_DIR/<rel> to BUNDLE/<rel>, preserving layout. Extra args are
# passed to `find` so we can ship only the file types actually consumed.
# Paths that were asked for but are not in SOURCE_DIR. Collected rather than
# fatal-on-first, so one run tells you everything that is wrong with the source
# tree instead of making you fix them one at a time. Checked before the tarball
# is written - see the guard at the end.
MISSING_PATHS=()

copy_tree() {
    local rel="$1"; shift
    local src="${SOURCE_DIR}/${rel}"
    if [ ! -e "${src}" ]; then
        echo "  MISSING: ${rel}" >&2
        # Guard against double-reporting: two calls ship different file types
        # out of the same meat clean/ directory.
        local seen
        for seen in ${MISSING_PATHS[@]+"${MISSING_PATHS[@]}"}; do
            [ "${seen}" = "${rel}" ] && return 0
        done
        MISSING_PATHS+=("${rel}")
        return 0
    fi
    mkdir -p "${BUNDLE}/${rel}"
    if [ "$#" -gt 0 ]; then
        # Selective copy: only files matching the filter.
        (cd "${src}" && find . -type f \( "$@" \) -print0) \
            | (cd "${src}" && tar --null -T - -cf -) \
            | (cd "${BUNDLE}/${rel}" && tar -xf -)
    else
        cp -r "${src}/." "${BUNDLE}/${rel}/"
    fi
    echo "  added: ${rel}  ($(du -sh "${BUNDLE}/${rel}" | cut -f1))"
}

copy_file() {
    local rel="$1"
    local src="${SOURCE_DIR}/${rel}"
    if [ ! -e "${src}" ]; then
        echo "  MISSING: ${rel}" >&2
        MISSING_PATHS+=("${rel}")
        return 0
    fi
    mkdir -p "${BUNDLE}/$(dirname "${rel}")"
    cp "${src}" "${BUNDLE}/${rel}"
    echo "  added: ${rel}  ($(du -sh "${BUNDLE}/${rel}" | cut -f1))"
}

echo "[1/4] Simulated training dataset (~245 MB)"
copy_tree "difftactile/output/training_data/pickle_20250901_220921_reordered_dense"

echo "[2/4] Real experimental data"
# Silicone: only the final _dense stage is consumed by the GNN.
copy_tree "difftactile/manual_or_experimental_data/silicone_training_data/20250901-131547_dense"
# Meat: training reads only the two .npz per trial. `frames.mp4` is the 26-frame
# decimated recording per trial (~2.3 MB, ~52 MB total), included so the
# annotation viewer can draw the labels over the real camera images; its frames
# correspond 1:1 with marker_labels.npz. Built by
# `script_make_meat_clean_videos` from meat_training_data/raw/, which is NOT
# shipped (1.6 GB). The old marker_labels.avi overlays (81 MB) stay excluded -
# frames.mp4 plus the labels reproduces them at a fraction of the size.
copy_tree "difftactile/manual_or_experimental_data/meat_training_data/clean" -name '*.npz'
copy_tree "difftactile/manual_or_experimental_data/meat_training_data/clean" -name 'frames.mp4'

echo "[3/4] Trained checkpoints"
copy_file "saved_models_sim/final_segmentation_model_gnn_sim.pt"
copy_file "saved_models_meat/final_segmentation_model_gnn_meat.pt"

echo "[4/5] Small artifacts required by the ML entrypoints"
copy_file "difftactile/output/test_loader_gnn_sim.pickle"
copy_file "difftactile/output/test_loader_gnn_meat.pickle"

echo "[5/5] Sensor geometry / marker layout (~5 MB)"
# Derived from the sensor CAD and a reference photo of the undeformed sensor.
# Regenerable in principle (gmsh mesh generation + marker detection), but they
# are small, they never change, and every simulator run needs them - shipping
# them removes a long chain of setup steps before the simulator will start.
copy_file "difftactile/output/base-graph-connectivity.npz"
copy_file "difftactile/output/marker_locations_ordered.npz"
copy_file "difftactile/output/init-marker-positions.npz"
copy_file "difftactile/output/init-marker-positions.pkl"
copy_file "difftactile/output/gmsh_mesh_vitactip.pkl"
copy_file "difftactile/output/gmsh_mesh_vein.pkl"
copy_file "difftactile/output/vitactip_mesh.npz"
copy_file "difftactile/output/edge_lengths.pkl"
copy_file "difftactile/output/tactile_sensor.f2v.pkl"
copy_file "difftactile/output/phantom_points.npz"
copy_file "difftactile/output/vein_points.npz"
copy_file "difftactile/output/is_fixed_layer.npz"
copy_file "difftactile/output/grid_node_v0_mask.npz"
copy_file "difftactile/output/initial_vertex_positions_undeformed.pkl"
copy_file "difftactile/output/vitactip_points_E.pkl"
# System-identification marker tracks: the simulator loads these at start-up to
# align its contact model against the real sensor (main.py load_system_identification_data).
copy_tree "difftactile/output/marker_tracker/domain-adaptation-vascular-markers"

# Published domain-adaptation BO runs. These are the fitted searches behind the
# adopted simulator parameters: the per-iteration history, the GP observations
# (enough to refit the surrogates without re-simulating), the convergence figure
# and the alignment overlays.
#
# Deliberately EXCLUDES the `snapshots/` subdirectory, which is ~16 MB of
# rendered PNGs per run and is regenerable from the recorded parameters - it is
# a debugging aid, not an artifact. The JSON and the overlays are what the
# results depend on, and they are tens of KB.
#
# The filter uses `! -path` rather than `-prune ... -print`: copy_tree appends
# its own `-print0` for tar, and an inner `-print` would make find emit
# newline-separated names into a `tar --null` reader, which mangles every path.
copy_tree "difftactile/output/domain_adaptation_published" \
    '(' -name '*.json' -o -name '*.png' -o -name '*.npz' -o -name '*.csv' ')' \
    -a ! -path '*/snapshots/*'

# Ship the manifest and the restore script inside the archive too, so the
# download is self-describing even if separated from the repository.
cp "${SCRIPT_DIR}/MANIFEST.md" "${BUNDLE}/MANIFEST.md" 2>/dev/null || true
cp "${SCRIPT_DIR}/restore_data.sh" "${BUNDLE}/restore_data.sh" 2>/dev/null || true

# --- refuse to ship an incomplete bundle --------------------------------------
#
# Every path above is in the bundle because it cannot be regenerated (or costs
# hours of GPU time), so a missing one is a broken artifact, not a warning. This
# used to `return 0` and carry on, which produced a plausible-looking tarball
# that was quietly missing whole datasets - the failure only surfaced later, for
# whoever downloaded it. Fail here instead.
#
# DIFFTACTILE_BUNDLE_ALLOW_MISSING=1 overrides, for deliberately partial builds.
if [ "${#MISSING_PATHS[@]}" -gt 0 ]; then
    if [ "${DIFFTACTILE_BUNDLE_ALLOW_MISSING:-}" = "1" ]; then
        echo
        echo "WARNING: ${#MISSING_PATHS[@]} path(s) missing; continuing because" >&2
        echo "DIFFTACTILE_BUNDLE_ALLOW_MISSING=1. The bundle is INCOMPLETE." >&2
    else
        echo
        echo "ERROR: ${#MISSING_PATHS[@]} path(s) are not in the source tree, so the" >&2
        echo "bundle would be incomplete. No tarball written." >&2
        echo >&2
        printf '  %s\n' "${MISSING_PATHS[@]}" >&2
        echo >&2
        echo "Source tree was: ${SOURCE_DIR}" >&2
        echo >&2
        echo "The default source is the repository itself, which is the authoritative" >&2
        echo "copy of the data. If you passed the frozen submission-state snapshot," >&2
        echo "note that it predates the meat-dataset rename and the checkpoint path" >&2
        echo "renames, so most of these will be missing from it - bundle from the" >&2
        echo "repository instead. Otherwise restore the data bundle first:" >&2
        echo >&2
        echo "    ./data/restore_data.sh <tarball>" >&2
        echo >&2
        echo "Set DIFFTACTILE_BUNDLE_ALLOW_MISSING=1 to build a partial bundle anyway." >&2
        exit 1
    fi
fi

echo
echo "Bundle contents: $(du -sh "${BUNDLE}" | cut -f1)"
echo "Compressing to ${OUTPUT_TAR} ..."
tar -czf "${OUTPUT_TAR}" -C "${STAGE}" shallow-vessel-palpation-data

echo
echo "Done: ${OUTPUT_TAR}  ($(du -sh "${OUTPUT_TAR}" | cut -f1))"
echo "SHA256:"
sha256sum "${OUTPUT_TAR}"
